import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.25.1";
import { z as z3 } from "npm:zod@^3.25.76";
var search_certificates_default = defineTool3({
  name: "search_certificates",
  title: "Search certificate applications",
  description: "Search Warish and Dependent applications by applicant name, village, memo number, certificate number, or verification id.",
  inputSchema: {
    query: z3.string().describe("Free text to match against name, village, memo or certificate number."),
    limit: z3.number().int().optional().describe("Max rows per register (default 10, max 50).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ query, limit }, ctx) => {
    if (!ctx.isAuthenticated()) return unauthenticated();
    const take = Math.min(Math.max(limit ?? 10, 1), 50);
    const term = query.trim().slice(0, 100);
    if (!term) return errorResult("Search query is empty.");
    const safe = term.replace(/[,.()"\\*]/g, " ").replace(/\s+/g, " ").trim();
    if (!safe) return errorResult("Search query contains no searchable characters.");
    const like = `"%${safe}%"`;
    const filter = [
      `applicant_name.ilike.${like}`,
      `village.ilike.${like}`,
      `memo_no.ilike.${like}`,
      `certificate_number.ilike.${like}`,
      `verification_id.ilike.${like}`
    ].join(",");
    const supabase = supabaseForUser(ctx);
    const results = {};
    for (const [kind, table] of Object.entries(CERT_TABLES)) {
      const { data, error } = await supabase.from(table).select(LIST_COLUMNS).or(filter).order("updated_at", { ascending: false }).limit(take);
      if (error) return errorResult(`${kind}: ${error.message}`);
      results[kind] = data ?? [];
    }
    return jsonResult({ query: term, results });
  }
});

// src/lib/mcp/tools/queue-summary.ts
import { defineTool as defineTool4 } from "npm:@lovable.dev/mcp-js@0.25.1";
var STATUSES = ["Draft", "Submitted", "Under Review", "Approved", "Rejected", "Issued"];
var queue_summary_default = defineTool4({
  name: "queue_summary",
  title: "Certificate queue summary",
  description: "Live counts of Warish and Dependent applications by workflow status, plus items returned for modification.",
  inputSchema: {},
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async (_input, ctx) => {
    if (!ctx.isAuthenticated()) return unauthenticated();
    const supabase = supabaseForUser(ctx);
    const summary = {};
    for (const [kind, table] of Object.entries(CERT_TABLES)) {
      const counts = {};
      for (const status of STATUSES) {
        const { count, error } = await supabase.from(table).select("id", { count: "exact", head: true }).eq("status", status);
        if (error) return errorResult(`${kind}: ${error.message}`);
        counts[status] = count ?? 0;
      }
      const { count: returned, error: returnedError } = await supabase.from(table).select("id", { count: "exact", head: true }).like("rejection_reason", "[RETURN]%");
      if (returnedError) return errorResult(`${kind}: ${returnedError.message}`);
      counts["Returned for modification"] = returned ?? 0;
      summary[kind] = counts;
    }
    return jsonResult(summary);
  }
});

